"Реки текут к морям": "Өзендер теңіздерге ағады",
"Что загрязняет воду?": "Суды не ластайды?",
"мусор и стоки заводов": "қоқыс және зауыттардың ағынды суы",
"Отходы губят воду": "Қалдықтар суды құртады",
