"ураган": "дауыл",
"Разложи по корзинам.": "Себеттерге бөліп салыңыз.",
"Выбери карточку, потом корзину": "Карточканы таңдаңыз, сосын себетті",
"Подумай, к какой группе относится каждая карточка.": "Әр карточка қай топқа жататынын ойланыңыз.",
"деревья": "ағаштар",
