"Естествознание 4 класс — Білім Аралы": "Жаратылыстану 4-сынып — Білім Аралы",
"Низшие и высшие растения и их защита — Білім Аралы": "Төменгі және жоғарғы сатыдағы өсімдіктер және оларды қорғау — Білім Аралы",
