"Пчела получает нектар, цветок — опыление.": "Ара нектар алады, гүл — тозаңдану.",
"Пыльник раскрывается и высыпает пыльцу": "Тозаңқап ашылып, тозаңды шашады",
"Пыльник раскрывается, и пыльца высыпается": "Тозаңқап ашылады да, тозаң шашылады",
"Пыльца должна попасть на рыльце": "Тозаң аналық мойнына түсуі керек",
"Пыльца ложится на рыльце": "Тозаң аналық мойнына қонады",
"Пыльца образуется в пыльниках тычинок.": "Тозаң аталықтардың тозаңқаптарында түзіледі.",
"Пыльца переносится на цветках": "Тозаң гүлдерде тасымалданады",
