"Разложи карточки по ролям в цепи. Выбери, к какой группе относится каждая.": "Карточкаларды тізбектегі рөлдері бойынша бөл. Әрқайсысы қай топқа жататынын таңда.",
"Разложи карточки по стадиям развития растения.": "Карточкаларды өсімдіктің даму кезеңдері бойынша орналастыр.",
"Разложи особенности семян по способам распространения.": "Тұқымдардың ерекшеліктерін таралу тәсілдері бойынша бөл.",
"Разложи по группам.": "Топтарға бөл.",
"Разложи растения по способам распространения их семян.": "Өсімдіктерді тұқымдарының таралу тәсілдері бойынша бөл.",
"Распространение семян помогает растениям занять новые места.": "Тұқымдардың таралуы өсімдіктерге жаңа жерлерді алуға көмектеседі.",
"Расселение даёт больше места и света": "Таралу көбірек орын мен жарық береді",
"Растение катится по степи": "Өсімдік дала бойымен домалайды",
"Растение само создаёт питательные вещества": "Өсімдік қоректік заттарды өзі жасайды",
"Растение создаёт питательные вещества": "Өсімдік қоректік заттарды жасайды",
"Растение создаёт питательные вещества на свету.": "Өсімдік қоректік заттарды жарықта жасайды.",
"Растения дают кислород, пищу, лекарства и материалы, а ещё дом и тень зверям и птицам.": "Өсімдіктер оттек, азық, дәрі және материал береді, сондай-ақ аңдар мен құстарға үй мен көлеңке болады.",
"Растения дают кислород.": "Өсімдіктер оттек береді.",
"Растения используют свет Солнца": "Өсімдіктер Күннің жарығын пайдаланады",
"Растения нужно перетирать": "Өсімдіктерді ұсақтап қажау керек",
"Растения нужны всем. Нажимай на карточки.": "Өсімдіктер бәріне қажет. Карточкаларды бас.",
"Растения сами создают питательные вещества на свету. Поэтому пищевая цепь всегда начинается с растения.": "Өсімдіктер қоректік заттарды жарықта өздері жасайды. Сондықтан қоректік тізбек әрқашан өсімдіктен басталады.",
"Растения создают питательные вещества на свету. Их едят растительноядные животные, а тех — хищники. Так строится пищевая цепь.": "Өсімдіктер қоректік заттарды жарықта жасайды. Оларды шөпқоректі жануарлар жейді, ал оларды жыртқыштар жейді. Қоректік тізбек осылай құрылады.",
"Растения стоят в начале цепи": "Өсімдіктер тізбектің басында тұрады",
"Растительноядное": "Шөпқоректі",
"Редкие виды могут исчезнуть": "Сирек түрлер жойылып кетуі мүмкін",
"Редкий цветок нужно оставить расти": "Сирек гүлді өсуге қалдыру керек",
"Результаты исследования можно оформить постером или схемой.": "Зерттеу нәтижесін плакатпен немесе сызбамен рәсімдеуге болады.",
"Рубить деревья можно, не сажая новых.": "Жаңасын отырғызбай, ағаштарды кесуге болады.",
"Рыльце — верхушка пестика": "Аналық мойны — аналықтың төбесі",
"Рядом с родителем растениям тесно": "Ата-анасының қасында өсімдіктерге тар",
"С чего начинается жизненный цикл растения?": "Өсімдіктің өмірлік циклі неден басталады?",
"С чего начинается любая пищевая цепь?": "Кез келген қоректік тізбек неден басталады?",
"Сажай деревья, не рви редкие цветы, туши костры. А чтобы изучать растения, выбирай наблюдение или эксперимент.": "Ағаш отырғыз, сирек гүлдерді жұлма, оттарды сөндір. Ал өсімдіктерді зерттеу үшін бақылауды немесе экспериментті таңда.",
"Сайгак пасётся в степи": "Киік далада жайылады",
"Сайгак питается травой.": "Киік шөппен қоректенеді.",
"Сайгак — степная антилопа": "Киік — дала антилопасы",
"Сайгак — травоядное животное.": "Киік — шөпқоректі жануар.",
"Сайгак — это морская рыба.": "Киік — теңіз балығы.",
"Сам плод": "Жемістің өзі",
"Самораспространение": "Өздігінен тарау",
"Саранча развивается с полным превращением.": "Сарышегіртке толық түрленіп дамиды.",
"Семена выходят с помётом далеко от дерева": "Тұқымдар саңғырықпен ағаштан алыс шығады",
"Семена кокоса не могут плавать.": "Кокос тұқымдары жүзе алмайды.",
"Семена образуются после опыления.": "Тұқымдар тозаңданудан кейін түзіледі.",
"Семена одного растения должны прорасти подальше друг от друга. Тогда им хватит места, света и воды.": "Бір өсімдіктің тұқымдары бір-бірінен алыс өнуі керек. Сонда оларға орын, жарық және су жеткілікті болады.",
"Семена созревают в плоде.": "Тұқымдар жемісте пісіп жетіледі.",
"Симбиоз приносит пользу обоим организмам.": "Симбиоз екі организмге де пайда келтіреді.",
"Симбиоз — отношения, выгодные обоим. Пчела получает нектар, а цветок — опыление.": "Симбиоз — екеуіне де тиімді қарым-қатынас. Ара нектар алады, ал гүл — тозаңдану.",
